// Stored variant + revision keep a work card stable across reloads and future releases.
export const BIKE_STYLES=[{name:'Stadtrad',color:0xa4684b,size:28,pressure:'3,5',top:1.12},{name:'Trekkingrad',color:0x447e86,size:28,pressure:'4,0',top:1.3},{name:'Mountainbike',color:0x6f8051,size:26,pressure:'2,5',top:1.3}];
export const orderBike=a=>BIKE_STYLES[(a?.variant??0)%3];
const step=(point,title,hint,choices,correct,minutes,gesture)=>({point,title,hint,choices,correct,minutes,gesture});
export function variedWorkshopSteps(a){
 const n=a.variant,b=orderBike(a),rear=n%2===1;
 if(a.type==='stock'){
  const item=['tube28','tube26','brake'][n%3],label={tube28:'28-Zoll-Schläuche',tube26:'26-Zoll-Schläuche',brake:'Bremsbeläge für Felgenbremsen'}[item],ordered=6+(n%4)*2,actual=ordered-(n%2),mark={tube28:'28/47–622',tube26:'35/47–559',brake:'V-Brake / 70 mm'}[item];
  return [step('workshopIntake','Karton öffnen und zählen',`Lieferschein: ${ordered} ${label}. Nach dem Öffnen zählst du ${actual} Packungen.`,[['complete','Vollständig erfassen'],['short','Fehlmenge dokumentieren']],actual===ordered?'complete':'short',12,'inspect'),step('workshopStock','Passendes Fach wählen',`Packungsaufdruck: ${mark} · ${label}.`,[['tube28','Fach: 28-Zoll-Schläuche'],['tube26','Fach: 26-Zoll-Schläuche'],['brake','Fach: Bremsbeläge']],item,14,'sort'),step('workshopTest','Zugang freigeben',`Erwartet: ${ordered}. Tatsächlich vorhanden: ${actual}. Verbucht wird die gezählte Menge.`,[[String(actual),`${actual} Packungen buchen`],[String(actual+1),`${actual+1} Packungen buchen`]],String(actual),10,'inspect')];
 }
 if(a.type==='check'){
  const fault=n%4,repair=['center','cable','pads','pressure'][fault],hints=['Ein Belag schleift. Hebelweg und Belagstärke sind in Ordnung.','Der Hebel reicht fast bis zum Lenker. Beide Beläge sind ausreichend dick.','Die Verschleißrillen beider Bremsbeläge sind nicht mehr sichtbar.','Beide Bremsen funktionieren. Der Reifen fühlt sich weich an; das Manometer zeigt 1,2 bar.'],tools=['allen5','allen5','pads','pump'],toolLabels=['5-mm-Inbusschlüssel','5-mm-Inbusschlüssel','V-Brake-Beläge / 70 mm','Standpumpe mit Manometer'];
  return [step('workshopBike','Befund am Fahrrad prüfen',`${b.name}: ${hints[fault]}`,[['center','Bremse zentrieren'],['cable','Bremszug nachstellen'],['pads','Bremsbeläge ersetzen'],['pressure','Reifendruck korrigieren']],repair,14,'inspect'),step('workshopStock','Werkzeug und Material holen',`Arbeitskarte: ${toolLabels[fault]}. ${fault===3?'Freigegebener Druck: '+b.pressure+' bar.':''}`,[['allen5','5-mm-Inbusschlüssel'],['pads','V-Brake-Beläge / 70 mm'],['pump','Standpumpe mit Manometer']],tools[fault],7,'collect'),step('workshopBike',fault===3?'Reifen aufpumpen':fault===2?'Neue Beläge montieren':'Bremse einstellen',fault===3?`Auf ${b.pressure} bar einstellen, nicht auf den Maximalwert der Pumpe.`:fault===2?'Beläge auf der Felgenflanke ausrichten. Sie dürfen den Reifen nicht berühren.':fault===1?'Zug schrittweise spannen. Am Hebel muss Reserve bleiben.':'Beide Beläge brauchen gleichen Abstand zur Felge.',[['adjust',fault===3?`${b.pressure} bar einstellen`:fault===2?'Beläge auf der Felge ausrichten':'Schrittweise einstellen'],['force',fault===3?'Bis zum Pumpenmaximum füllen':'Ohne Abstandsprüfung festziehen']],'adjust',17,fault===3?'pump':'wrench'),step('workshopBike','Sicherheitsprüfung',fault===3?'Druckhaltung, Ventil und Reifensitz prüfen.':'Freies Drehen und beide Bremsen unter Handdruck prüfen.',[['both','Alle genannten Prüfungen ausführen'],['look','Nur kurz ansehen']],'both',13,'test')];
 }
 const cause=n%3,causes=['Ein Glasstück steckt noch im Mantel.','Das Felgenband ist verrutscht; eine Speichenbohrung liegt frei.','Am Ventilfuß ist ein Riss. Mantel und Felgenband sind unbeschädigt.'];
 return [step('workshopBike','Rad prüfen und ausbauen',`${b.name}, ${b.size} Zoll: Am ${rear?'Hinterrad':'Vorderrad'} entweicht Luft. Das andere Rad hält den Druck.`,[['front','Vorderrad ausbauen'],['rear','Hinterrad ausbauen']],rear?'rear':'front',14,'inspect'),step('workshopStock','Passenden Schlauch holen',`Reifenflanke: ${b.size===28?'37–622':'40–559'}. Benötigt wird ein ${b.size}-Zoll-Schlauch.`,[['tube28','Schlauch 28/47–622'],['tube26','Schlauch 35/47–559']],b.size===28?'tube28':'tube26',8,'collect'),step('workshopBench','Schadensursache beheben',causes[cause],[['glass','Fremdkörper entfernen, Mantel prüfen'],['band','Felgenband korrekt ausrichten'],['valve','Defekten Schlauch ersetzen, Ventilloch prüfen']],['glass','band','valve'][cause],16,'inspect'),step('workshopBike','Schlauch und Rad einsetzen','Schlauch vorfüllen, Ventil gerade ausrichten, Reifen ohne Einklemmen montieren. Rad anschließend sicher befestigen.',[['seat','Gleichmäßig einsetzen und Befestigung prüfen'],['force','Mit Metallwerkzeug gewaltsam aufhebeln']],'seat',22,'wrench'),step('workshopBike','Druck und Sicherheit prüfen',`Arbeitskarte: ${b.pressure} bar. Befestigung, Reifensitz und Druckhaltung kontrollieren.`,[['safe',`${b.pressure} bar · alle Prüfungen ausführen`],['max','6 bar · keine Nachkontrolle']],'safe',16,'test')];
}
